// OP-151 m.3 (e), OP-149 m.6, TN-128, X11: the console session's device Instance. Its P-256
// key is generated by WebCrypto as non-extractable and kept in IndexedDB; it never leaves this
// browser. AIS bytes are encoded by the Kernel (Wasm); WebCrypto signs them. A stolen cookie,
// in a browser without this key, can neither write nor read authority state.
import { loadKernel, type Kernel } from "@esuiss/access";

import { b64url, call, fromB64url, json, Problem } from "./api.js";

const DB = "access-console";
const STORE = "instances";
const PEP = "access-console";
const READ_CONTEXT = "access/console-read/v1";
const ESP256 = -9;
// P-256 group order (SEC 2) for the low-S form the Kernel requires (CR-9)
const N = 0xffffffff00000000ffffffffffffffffbce6faada7179e84f3b9cac2fc632551n;

/** What a signature screen shows: the Kernel's decoding of the exact bytes to be signed. */
export interface SignatureView {
  readonly statement: DecodedStatement;
  readonly intents: readonly DecodedIntent[];
}

export interface DecodedStatement {
  readonly domain: string;
  readonly nonce: string;
  readonly intent: string;
  readonly mode: "commit" | "continue" | "check";
  readonly pep: string;
  readonly capacity: "own" | { readonly for: string };
  readonly iat: string;
}

export interface DecodedIntent {
  readonly digest: string;
  readonly action: { readonly namespace: string; readonly name: string; readonly major: string };
  readonly resources: readonly {
    readonly namespace: string;
    readonly path: readonly string[];
  }[];
  readonly params: Readonly<Record<string, string>>;
  readonly validity: { readonly from: string; readonly until: string };
}

/** Shows `view` on the signature screen; resolves `true` only when the user signs. */
export type Confirm = (view: SignatureView) => Promise<boolean>;

/** A device Instance as this browser keeps it. */
export interface Instance {
  readonly id: string;
  readonly key: CryptoKey;
  readonly kid: Uint8Array;
  readonly domain: Uint8Array;
  readonly basis: Uint8Array;
  readonly pep: string;
}

function open(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const r = indexedDB.open(DB, 1);
    r.onupgradeneeded = () => {
      r.result.createObjectStore(STORE, { keyPath: "id" });
    };
    r.onsuccess = () => {
      resolve(r.result);
    };
    r.onerror = () => {
      reject(r.error ?? new Error("indexeddb"));
    };
  });
}

async function tx<T>(mode: IDBTransactionMode, f: (s: IDBObjectStore) => IDBRequest): Promise<T> {
  const db = await open();
  return new Promise<T>((resolve, reject) => {
    const r = f(db.transaction(STORE, mode).objectStore(STORE));
    r.onsuccess = () => {
      resolve(r.result as T);
    };
    r.onerror = () => {
      reject(r.error ?? new Error("indexeddb"));
    };
  });
}

/** The record id: one key per account, realm and console session's Instance kid. */
function recordId(realm: string, account: string, kid: string): string {
  return `${realm}/${account}/${kid}`;
}

/** This browser's key for the session's registered Instance `kid`, if it has it. */
export async function find(
  realm: string,
  account: string,
  kid: string | null,
): Promise<Instance | undefined> {
  if (kid === null) return undefined;
  try {
    return await tx<Instance | undefined>("readonly", (s) => s.get(recordId(realm, account, kid)));
  } catch {
    return undefined;
  }
}

function lowS(sig: Uint8Array): Uint8Array {
  const hex = (b: Uint8Array) => Array.from(b, (x) => x.toString(16).padStart(2, "0")).join("");
  const s = BigInt(`0x${hex(sig.slice(32))}`);
  if (s <= N / 2n) return sig;
  const t = (N - s).toString(16).padStart(64, "0");
  const out = Uint8Array.from(sig);
  for (let i = 0; i < 32; i++) out[32 + i] = Number.parseInt(t.slice(i * 2, i * 2 + 2), 16);
  return out;
}

function nonce(): Uint8Array {
  return crypto.getRandomValues(new Uint8Array(16));
}

async function sign(key: CryptoKey, k: Kernel, kid: Uint8Array, statement: Uint8Array) {
  const protectedHeader = k.aisProtected(ESP256, kid);
  const tbs = Uint8Array.from(k.coseToBeSigned(protectedHeader, statement));
  const raw = new Uint8Array(
    await crypto.subtle.sign({ name: "ECDSA", hash: "SHA-256" }, key, tbs),
  );
  return b64url(k.coseSign1(protectedHeader, statement, lowS(raw)));
}

function decodedIntent(k: Kernel, envelope: Uint8Array): DecodedIntent {
  return JSON.parse(k.describeIntent(envelope)) as DecodedIntent;
}

function decodedStatement(k: Kernel, statement: Uint8Array): DecodedStatement {
  return JSON.parse(k.describeStatement(statement)) as DecodedStatement;
}

/** A signature screen refusal: the user cancelled, or the bytes did not match the view. */
export class NotSigned extends Error {}

interface Challenge {
  readonly challenge: string;
  readonly domain: string;
  readonly basis: string;
  readonly pep?: string;
  readonly party: string;
  readonly valid_from: string;
  readonly valid_until: string;
  readonly create: string;
  readonly register?: string;
}

/**
 * Registers this browser as the console session's device Instance (OP-149 m.6): a fresh
 * non-extractable P-256 key, its own `instance_create` Exercise signed after the signature
 * screen showed the Kernel's decoding of the intents, the key kept in IndexedDB.
 */
export async function register(
  realm: string,
  account: string,
  confirm: Confirm,
): Promise<Instance> {
  const k = await loadKernel();
  const pair = await crypto.subtle.generateKey({ name: "ECDSA", namedCurve: "P-256" }, false, [
    "sign",
  ]);
  const raw = new Uint8Array(await crypto.subtle.exportKey("raw", pair.publicKey));
  const [x, y] = [raw.slice(1, 33), raw.slice(33, 65)];
  const kid = k.thumbprintP256(x, y);
  const coseKey = k.coseKeyP256(x, y);
  const c = await json<Challenge>("/instances/challenge", {
    method: "POST",
    body: { key: b64url(coseKey) },
  });
  const domain = fromB64url(c.domain);
  const basis = k.exerciseBasis("public", fromB64url(c.basis));
  const pep = c.pep ?? PEP;
  const challenge = fromB64url(c.challenge);
  const envelopes = [c.create, ...(c.register === undefined ? [] : [c.register])].map(fromB64url);
  const nonces = [challenge, Uint8Array.from([...challenge, 0x01])];
  const iat = BigInt(Date.now());
  const statements = envelopes.map((e, i) =>
    k.aisStatement(
      domain,
      nonces[i] ?? challenge,
      k.intentDigest(e),
      "commit",
      pep,
      new Uint8Array(),
      basis,
      iat,
      new Uint8Array(),
    ),
  );
  const intents = envelopes.map((e) => decodedIntent(k, e));
  const first = statements[0];
  if (first === undefined) throw new NotSigned("no statement");
  const view: SignatureView = { statement: decodedStatement(k, first), intents };
  if (!(await confirm(view))) throw new NotSigned("cancelled");
  const signed = await Promise.all(statements.map((s) => sign(pair.privateKey, k, kid, s)));
  const body: Record<string, string> = {
    challenge: c.challenge,
    party: c.party,
    key: b64url(coseKey),
    valid_from: c.valid_from,
    valid_until: c.valid_until,
    ais: signed[0] ?? "",
  };
  if (signed[1] !== undefined) body["register_ais"] = signed[1];
  await json("/instances", { method: "POST", body });
  const instance: Instance = {
    id: recordId(realm, account, b64url(kid)),
    key: pair.privateKey,
    kid,
    domain,
    basis,
    pep,
  };
  await tx("readwrite", (s) => s.put(instance));
  return instance;
}

/** The read proof's intent: `SHA-256("access/console-read/v1" ‖ 0x00 ‖ method ‖ " " ‖ target)`. */
export async function readIntent(method: string, target: string): Promise<Uint8Array> {
  const enc = new TextEncoder();
  const bytes = Uint8Array.from([
    ...enc.encode(READ_CONTEXT),
    0,
    ...enc.encode(`${method} ${target}`),
  ]);
  return new Uint8Array(await crypto.subtle.digest("SHA-256", bytes));
}

/**
 * A CT0 read through the admin proxy (TN-128): the request carries a read proof, an AIS in
 * `check` mode over this very request. Reads are not consent, so no signature screen opens.
 */
export async function adminRead(instance: Instance, path: string): Promise<Response> {
  const k = await loadKernel();
  const target = `/admin/v1/${path}`;
  const statement = k.aisStatement(
    instance.domain,
    nonce(),
    await readIntent("GET", target),
    "check",
    instance.pep,
    new Uint8Array(),
    instance.basis,
    BigInt(Date.now()),
    new Uint8Array(),
  );
  const ais = await sign(instance.key, k, instance.kid, statement);
  return call(`/proxy/admin/${path}`, { headers: { "x-access-ais": ais } });
}

/**
 * A write through the admin proxy (TN-110, MD-14): the signature screen shows the Kernel's
 * decoding of `envelope` and of the statement about to be signed; only after the user signs
 * does WebCrypto sign. The AIS nonce is the `Idempotency-Key` (TN-126).
 */
export async function adminWrite(
  instance: Instance,
  confirm: Confirm,
  method: "POST" | "PUT" | "PATCH" | "DELETE",
  path: string,
  envelope: Uint8Array,
  body: unknown,
): Promise<Response> {
  const k = await loadKernel();
  const n = nonce();
  const intent = k.intentDigest(envelope);
  const statement = k.aisStatement(
    instance.domain,
    n,
    intent,
    "commit",
    instance.pep,
    new Uint8Array(),
    instance.basis,
    BigInt(Date.now()),
    new Uint8Array(),
  );
  const shown = decodedStatement(k, statement);
  const decoded = decodedIntent(k, envelope);
  if (shown.intent !== decoded.digest) {
    throw new NotSigned("mismatch");
  }
  if (!(await confirm({ statement: shown, intents: [decoded] }))) throw new NotSigned("cancelled");
  const ais = await sign(instance.key, k, instance.kid, statement);
  return call(`/proxy/admin/${path}`, {
    method,
    body,
    headers: { "x-access-ais": ais, "idempotency-key": b64url(n) },
  });
}

export { Problem };
